import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import Calculator from '@/components/Calculator';
import './styles.css';

// Share links carry the expression as ?expr=<url-encoded expression>.
const initialExpression = new URLSearchParams(window.location.search).get('expr') ?? '';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <Calculator initialExpression={initialExpression} />
  </StrictMode>
);

// The service worker precaches the whole build, so the installed app works offline.
// It is only generated by production builds; registering it under the dev server
// would serve stale bundles.
if (process.env.NODE_ENV === 'production' && 'serviceWorker' in navigator) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch((error: unknown) => {
      console.error('Service worker registration failed', error);
    });
  });
}
